def amplitude (d : MediumAtom) (Z : ℝ) (p r s w : ℕ) (h : ℤ) : ℂ :=
  let L := (p * (r * s)).lcm (p * w)
  let T := d.V / (L : ℝ)
  if h = 0 then 0 else
    (poissonSmoothLowPass (T * (h : ℝ) / Z) : ℂ) *
      (T • (𝓕 dyadicCutoffSchwartz) (T * (h : ℝ)))

def MediumAtom.cleanedAlpha (d : MediumAtom) (n : ℕ) : ℂ :=
  if (n : ℤ) ∣ d.residue then 0 else d.alpha n

def MediumAtom.divisorAlpha (d : MediumAtom) (n : ℕ) : ℂ :=
  if (n : ℤ) ∣ d.residue then d.alpha n else 0

def MediumAtom.cleanedAlphaAtom (d : MediumAtom) : MediumAtom :=
  { d with alpha := d.cleanedAlpha }

def CommonSmoothCutoff.poissonNonzeroFrequencyWindow (H : ℕ) : Finset ℤ :=
  ((Finset.Icc 1 H).image (fun n : ℕ => (n : ℤ))) ∪
    ((Finset.Icc 1 H).image (fun n : ℕ => -(n : ℤ)))

def CommonSmoothCutoff.poissonSmoothLowPass (u : ℝ) : ℝ :=
  CommonSmoothCutoff.dyadicBump (3 / 2 + u / 2)

def MediumAtom.sharedSmoothFrequencyBound (d : MediumAtom) (Z : ℝ) (D : ℕ) : ℕ :=
  Nat.ceil (64 * Z * d.Q1 * d.Q3 ^ 2 * d.Q2 ^ 2 / ((D : ℝ) * d.V))
